#!/usr/bin/env python3
import base64, os, sys, subprocess, time, py_compile, urllib.request

REPO = os.path.expanduser("~/Red-team-tauri")
os.chdir(REPO)

FILES = {
    "osint_new_endpoints.py": "",
    "tauri-frontend/src/components/OSINTPanel.tsx": "",
    "tauri-frontend/src/lib/authFetchInterceptor.ts": "",
}

print("=== SOURCESEAL OSINT DEPLOY ===")

# 1. Escribir archivos
for path, b64 in FILES.items():
    full = os.path.join(REPO, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "wb") as f:
        f.write(base64.b64decode(b64))
    print("  OK " + path)

# 2. Parchar backend
backend = os.path.join(REPO, "redteam/scripts/dashboard_server.py")
with open(backend, "r") as f:
    content = f.read()

has_dns = any("@app.get" in l and "osint/dns" in l for l in content.split(chr(10)))
if has_dns:
    print("  SKIP endpoints ya presentes")
else:
    new_code = base64.b64decode(FILES["osint_new_endpoints.py"]).decode()
    marker = "# == END OSINT ENGINE ==="
    idx = content.find(marker)
    if idx == -1:
        for m in ["# == END OSINT", "# END OSINT", "END OSINT ENGINE"]:
            idx = content.find(m)
            if idx != -1: break
    if idx != -1:
        content = content[:idx] + new_code + chr(10) + chr(10) + content[idx:]
        with open(backend, "w") as f: f.write(content)
        print("  OK endpoints insertados")
    else:
        print("  FAIL marcador no encontrado")
        sys.exit(1)

# 3. Sintaxis
py_compile.compile(backend, doraise=True)
print("  OK sintaxis Python")

# 4. Build frontend
os.chdir(os.path.join(REPO, "tauri-frontend"))
r = subprocess.run(["npm", "run", "build"], capture_output=True, text=True)
if r.returncode == 0: print("  OK build frontend")
else: print("  FAIL build"); sys.exit(1)
os.chdir(REPO)

# 5. Reiniciar
subprocess.run(["pkill", "-f", "dashboard_server.py"], capture_output=True)
time.sleep(2)
subprocess.Popen(["bash", "start-termux.sh"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
time.sleep(5)
try:
    urllib.request.urlopen("http://localhost:8001/api/health", timeout=5)
    print("  OK backend saludable")
except: print("  WARN backend arrancando")
print()
print("=== DESPLIEGUE COMPLETO ===")
print("Dashboard: http://localhost:8001/dashboard")